"""Bind exact original T68.05 criteria and variants to actual current evidence."""
import json
from common import ROOT,dump,read_json,sha
from check_metaprog_receivers import REPORT,COST,check
READINESS='research/v5/modern/metaprog_receivers_readiness.json'
def main():
    d,q=read_json(ROOT/REPORT),read_json(ROOT/COST);check(d,q)
    brief='curriculum/v5/exercises/X-T68-005.md';m=json.loads((ROOT/brief).read_text(encoding='utf8').split('```json\n',1)[1].split('\n```',1)[0]);teaching=[brief,'labs/metaprog/CONTRACTS.md','labs/metaprog/receivers/RECEIVERS.md','assessor/metaprog/receivers/ANALYSIS.md'];implementation=['assessor/metaprog/metaprog.c','assessor/metaprog/receivers/receivers.c','assessor/metaprog/receivers/receiver_macros.h','labs/metaprog/receivers/include/receivers.h','labs/metaprog/receivers/tests/tests.c','tools/verify_metaprog_receivers.py']
    claims=[
      'Four actual typed read functions preserve pointed-to const/volatile and expose distinct category markers, while generic selection chooses function designators before evaluating the single call argument. Typed write and observation APIs have narrower qualifier sets and no erased default. Retained numeric generic producer and MOD9/10 controls are actually imported and exercised.',
      'Exact N1570 generic/qualifier passages and the N2243 DR481 C17-marked corrigendum were read. Executed GCC/Clang probes distinguish top-level pointer const from pointee qualification and array decay. Nine negative translation specimens per compiler include unsupported/const writes, invalid unselected expression, duplicate compatible association, VLA/function association, discarded volatile and wrong device-view type. Explicit casts compile only and are not executed through an invalidly unqualified volatile-defined object. Published C17/C23 remain inaccessible.',
      'Six compiler profiles pass4anchors and8compiled ordinary semantic controls;4compiling learner stubs reject. Each matches4804 independent cases:3746accepted,26null-admission refusals,1032mask refusals and941exact callbacks. Exact callback-separated before/after observations use a legitimate mutable alias, not an asynchronous data race. Complete admitted access/output and mask semantics are checked, with seven equal-contract direct/generic samples, generated-code/stack/helper costs and build observations.',
      'Required volatile transfer includes distinct ordinary read/write-mask update and write-one-to-clear command views. Host synthetic RAM observes command values, never claims hardware clearing. Actual GCC assembly and Clang host/M4 O0/O3 IR show one-load/one-store update, store-only ack and two callback-separated reads; two M4 ELF32 links have zero undefined/dynamic imports and are explicitly not executed. Callback lifetime, const-view alias limits, no implicit atomicity/barrier and all13cost dimensions are explicit. Delayed author support is implemented without claiming independent learner/physical review.'
    ]
    criteria=[{**r,'author_readiness':'ready-bounded','demonstration':claim,'teaching':teaching,'implementation':implementation,'validation':[REPORT,COST],'independent_learner':'not-assessed','external_review':'not-run','physical_observation':'not-run-link-only-target'} for r,claim in zip(m['rubric'],claims)]
    updates=[]
    for identity in ['X-T68-005','X-T68-005-DELAYED','T68-05-TRANSFER','T68-05-INVESTIGATION']+[r['id'] for r in m['rubric']]:
        claim=next((r['demonstration'] for r in criteria if r['id']==identity),claims[3] if identity.endswith(('DELAYED','TRANSFER')) else ' '.join(claims))
        updates.append(dict(id=identity,dimensions={'teaching':dict(state='complete',evidence=teaching),'implementation':dict(state='complete',evidence=implementation),'author_validation':dict(state='passed',evidence=[REPORT,COST,READINESS]),'external_review':dict(state='not-run',evidence=[]),'independent_learner':dict(state='not-assessed',evidence=[]),'physical_observation':dict(state='not-run-link-only-target',evidence=[teaching[2]])},closure_rationale=claim+' Bounded author support only.'))
    g=read_json(ROOT/'research/v5/modern/ad_mp_gap_ledger.json')
    for row in g['gaps']:
        if row['id'] in ['T68-05-TRANSFER','T68-05-INVESTIGATION']:row.update(status='author-support-implemented-and-source-validated; independent-learner-not-assessed',author_evidence=[READINESS,REPORT,COST],remaining_external=['Unaided delayed learner attempt and per-objective assessment','Non-author assessment','Exact published C17/C23 access gaps remain'])
    dump(ROOT/'research/v5/modern/ad_mp_gap_ledger.json',g)
    inputs={**d['input_sha256'],**q['input_sha256']}
